PRAGMA foreign_keys = ON;

-- Interactive 32-question diagnostic created 2026-10-19.
-- Store in the published test library ONLY; teacher assigns to Karolína manually.
-- All physics wave phase conventions and necessary assumptions are explicit.
INSERT OR IGNORE INTO self_check_tests
  (id, slug, version, title, description, subject, topic, level, estimated_minutes, status)
VALUES ('mechanicke-vlneni-karolina-diagnostika-v1', 'mechanicke-vlneni-ss-karolina', '1', 'Mechanické vlnění — diagnostický self-check (SŠ, 32 úloh)', '[[calculator:Bez kalkulačky]]32 úloh / 64 bodů / cca 50 minut. Mechanické vlnění, rychlost, perioda, frekvence, vlnová délka, fáze a rovnice postupného vlnění. Čtyři úrovně obtížnosti. U každé úlohy vyber jednu správnou odpověď; po odevzdání uvidíš vysvětlení.', 'Fyzika', 'Mechanické vlnění', 'SŠ', '50', 'published');

INSERT OR IGNORE INTO self_check_questions
  (id, test_id, position, prompt, options_json, correct_answer, explanation, points)
VALUES
  ('mechanicke-vlneni-karolina-diagnostika-v1-q01', 'mechanicke-vlneni-karolina-diagnostika-v1', '1', '{"instruction":"Co se při mechanickém vlnění přenáší z jednoho místa na druhé?","math":"","category":"Základní pojmy a jednotky","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"Látka jako celek"},{"id":"b","label":"Energie, zatímco částice kmitají kolem rovnovážných poloh"},{"id":"c","label":"Pouze teplo bez kmitání"},{"id":"d","label":"Výhradně elektrický náboj"}]', 'b', 'Vlnění šíří kmitání a přenáší energii prostředím; látka se běžně nepřesouvá společně s vlnou.', '1'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q02', 'mechanicke-vlneni-karolina-diagnostika-v1', '2', '{"instruction":"Která věta popisuje příčné vlnění?","math":"","category":"Základní pojmy a jednotky","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"Částice kmitají kolmo ke směru šíření."},{"id":"b","label":"Částice kmitají jen ve směru šíření."},{"id":"c","label":"Vlnění se šíří pouze ve vakuu."},{"id":"d","label":"Částice musí urazit stejnou vzdálenost jako vlna."}]', 'a', 'U příčného vlnění je směr lokální výchylky částic kolmý na směr postupu vlny.', '1'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q03', 'mechanicke-vlneni-karolina-diagnostika-v1', '3', '{"instruction":"Který příklad je typicky podélné mechanické vlnění?","math":"","category":"Základní pojmy a jednotky","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"Vlnění na napnutém laně při kývání nahoru a dolů."},{"id":"b","label":"Světlo ve vakuu."},{"id":"c","label":"Zvuková vlna ve vzduchu."},{"id":"d","label":"Elektromagnetická vlna."}]', 'c', 'Zvuk ve vzduchu tvoří podélné změny hustoty a tlaku; částice vzduchu kmitají podél směru šíření.', '1'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q04', 'mechanicke-vlneni-karolina-diagnostika-v1', '4', '{"instruction":"Perioda vlnění je 2,5 ms. Jaká je frekvence?","math":"T=2{,}5\\,\\mathrm{ms}","category":"Základní pojmy a jednotky","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"250 Hz"},{"id":"b","label":"400 Hz"},{"id":"c","label":"40 Hz"},{"id":"d","label":"2 500 Hz"}]', 'b', '2,5 ms = 0,0025 s. f = 1/T = 400 Hz.', '1'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q05', 'mechanicke-vlneni-karolina-diagnostika-v1', '5', '{"instruction":"Frekvence je 250 Hz. Jaká je perioda?","math":"f=250\\,\\mathrm{Hz}","category":"Základní pojmy a jednotky","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"0,4 ms"},{"id":"b","label":"2,5 ms"},{"id":"c","label":"4 ms"},{"id":"d","label":"250 ms"}]', 'c', 'T=1/250 s = 0,004 s = 4 ms.', '1'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q06', 'mechanicke-vlneni-karolina-diagnostika-v1', '6', '{"instruction":"Vypočti rychlost vlnění.","math":"\\lambda=2{,}4\\,\\mathrm m,\\quad T=2\\,\\mathrm{ms}","category":"Základní pojmy a jednotky","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"1 200 m/s"},{"id":"b","label":"120 m/s"},{"id":"c","label":"4 800 m/s"},{"id":"d","label":"0,0048 m/s"}]', 'a', 'v = λ/T = 2,4/0,002 = 1 200 m/s.', '1'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q07', 'mechanicke-vlneni-karolina-diagnostika-v1', '7', '{"instruction":"Vypočti vlnovou délku.","math":"f=170\\,\\mathrm{Hz},\\quad v=340\\,\\mathrm{m/s}","category":"Základní pojmy a jednotky","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"0,5 m"},{"id":"b","label":"2 m"},{"id":"c","label":"170 m"},{"id":"d","label":"57 800 m"}]', 'b', 'λ=v/f=340/170=2 m.', '1'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q08', 'mechanicke-vlneni-karolina-diagnostika-v1', '8', '{"instruction":"Kolik metrů je 25 cm?","math":"","category":"Základní pojmy a jednotky","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"2,5 m"},{"id":"b","label":"0,025 m"},{"id":"c","label":"0,25 m"},{"id":"d","label":"250 m"}]', 'c', '25 cm = 25 × 0,01 m = 0,25 m.', '1'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q09', 'mechanicke-vlneni-karolina-diagnostika-v1', '9', '{"instruction":"Urči vlnovou délku.","math":"f=450\\,\\mathrm{Hz},\\quad v=360\\,\\mathrm{m/s}","category":"Vlnová délka a fázový rozdíl","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"0,8 m"},{"id":"b","label":"1,25 m"},{"id":"c","label":"162 m"},{"id":"d","label":"810 m"}]', 'a', 'λ=v/f=360/450=0,8 m.', '2'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q10', 'mechanicke-vlneni-karolina-diagnostika-v1', '10', '{"instruction":"Urči velikost fázového rozdílu dvou bodů vzdálených 0,20 m.","math":"\\lambda=0{,}80\\,\\mathrm m,\\quad\\Delta x=0{,}20\\,\\mathrm m","category":"Vlnová délka a fázový rozdíl","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"[[math:\\frac{\\pi}{4}]]"},{"id":"b","label":"[[math:\\frac{\\pi}{2}]]"},{"id":"c","label":"[[math:\\pi]]"},{"id":"d","label":"[[math:2\\pi]]"}]', 'b', 'Δφ=2π Δx/λ = 2π·0,20/0,80 = π/2 rad.', '2'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q11', 'mechanicke-vlneni-karolina-diagnostika-v1', '11', '{"instruction":"Dva nejbližší body mají opačnou fázi. Jak daleko jsou?","math":"\\lambda=4\\,\\mathrm m","category":"Vlnová délka a fázový rozdíl","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"1 m"},{"id":"b","label":"4 m"},{"id":"c","label":"2 m"},{"id":"d","label":"8 m"}]', 'c', 'Opačná fáze nastává při rozdílu π, tedy nejmenší vzdálenost je λ/2=2 m.', '2'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q12', 'mechanicke-vlneni-karolina-diagnostika-v1', '12', '{"instruction":"Jaká je nejmenší kladná vzdálenost různých bodů se stejnou fází?","math":"f=100\\,\\mathrm{Hz},\\quad v=5000\\,\\mathrm{m/s}","category":"Vlnová délka a fázový rozdíl","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"25 m"},{"id":"b","label":"100 m"},{"id":"c","label":"0,02 m"},{"id":"d","label":"50 m"}]', 'd', 'Stejná fáze se opakuje po λ=v/f=5000/100=50 m.', '2'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q13', 'mechanicke-vlneni-karolina-diagnostika-v1', '13', '{"instruction":"Jaká je nejmenší vzdálenost bodů s opačnou fází?","math":"f=725\\,\\mathrm{Hz},\\quad v=1450\\,\\mathrm{m/s}","category":"Vlnová délka a fázový rozdíl","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"1 m"},{"id":"b","label":"2 m"},{"id":"c","label":"0,5 m"},{"id":"d","label":"4 m"}]', 'a', 'λ=1450/725=2 m, vzdálenost pro opačnou fázi je λ/2=1 m.', '2'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q14', 'mechanicke-vlneni-karolina-diagnostika-v1', '14', '{"instruction":"Vlna vstoupí do nového prostředí a vlnová délka vzroste z 2 m na 3 m. Jaká bude rychlost?","math":"v_1=300\\,\\mathrm{m/s},\\ \\lambda_1=2\\,\\mathrm m,\\ \\lambda_2=3\\,\\mathrm m","category":"Vlnová délka a fázový rozdíl","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"200 m/s"},{"id":"b","label":"450 m/s"},{"id":"c","label":"600 m/s"},{"id":"d","label":"300 m/s"}]', 'b', 'Při přechodu se zachovává frekvence f=v1/λ1=150 Hz. Nová rychlost je v2=fλ2=450 m/s.', '2'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q15', 'mechanicke-vlneni-karolina-diagnostika-v1', '15', '{"instruction":"Fázový rozdíl je nezredukovaný 3π/2 rad. Urči vlnovou délku.","math":"\\Delta x=1{,}5\\,\\mathrm m,\\quad|\\Delta\\varphi|=\\frac{3\\pi}{2}","category":"Vlnová délka a fázový rozdíl","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"1 m"},{"id":"b","label":"1,5 m"},{"id":"c","label":"2 m"},{"id":"d","label":"3 m"}]', 'c', 'λ=2πΔx/Δφ=(2π·1,5)/(3π/2)=2 m.', '2'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q16', 'mechanicke-vlneni-karolina-diagnostika-v1', '16', '{"instruction":"Známe jen fázový rozdíl dvou bodů modulo 2π a jejich vzdálenost. Co obecně platí?","math":"","category":"Vlnová délka a fázový rozdíl","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"Vlnovou délku nemusí být možné určit jednoznačně."},{"id":"b","label":"Vždy existuje právě jedna vlnová délka."},{"id":"c","label":"Automaticky platí λ=Δx."},{"id":"d","label":"Fázový rozdíl nezávisí na vzdálenosti."}]', 'a', 'Různé nezredukované fázové posuny se mohou lišit o 2πk, ale popisovat stejné relativní fáze; bez omezení počtu celých vln nemáme jednoznačnou λ.', '2'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q17', 'mechanicke-vlneni-karolina-diagnostika-v1', '17', '{"instruction":"Urči periodu zdroje.","math":"y(0,t)=0{,}03\\sin(20\\pi t)","category":"Rovnice postupného vlnění","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"0,05 s"},{"id":"b","label":"0,10 s"},{"id":"c","label":"0,20 s"},{"id":"d","label":"10 s"}]', 'b', 'Úhlová frekvence ω=20π rad/s, tedy T=2π/ω=0,10 s.', '2'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q18', 'mechanicke-vlneni-karolina-diagnostika-v1', '18', '{"instruction":"Pro uvedenou vlnu šířící se do +x urči okamžitou výchylku.","math":"y(0,t)=0{,}03\\sin(20\\pi t),\\ v=200\\,\\mathrm{m/s},\\ x=5\\,\\mathrm m,\\ t=0{,}1\\,\\mathrm s","category":"Rovnice postupného vlnění","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"0 m"},{"id":"b","label":"+0,03 m"},{"id":"c","label":"−0,03 m"},{"id":"d","label":"+0,015 m"}]', 'c', 'T=0,1 s a λ=vT=20 m. Fáze=2π·(0,1/0,1−5/20)=3π/2, sin=−1. Výsledek −0,03 m.', '2'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q19', 'mechanicke-vlneni-karolina-diagnostika-v1', '19', '{"instruction":"Vlna má nulovou počáteční fázi. Jaká je okamžitá výchylka vzhledem k amplitudě?","math":"y=A\\sin[2\\pi(t/T-x/\\lambda)],\\quad t=T/2,\\quad x=\\lambda/4","category":"Rovnice postupného vlnění","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"−A"},{"id":"b","label":"A/2"},{"id":"c","label":"0"},{"id":"d","label":"A"}]', 'd', 'Fáze=2π(1/2−1/4)=π/2; proto y=A.', '2'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q20', 'mechanicke-vlneni-karolina-diagnostika-v1', '20', '{"instruction":"Za předpokladu nulové počáteční fáze urči amplitudu.","math":"t=T/2,\\quad x=\\lambda/3,\\quad y=5\\,\\mathrm{cm}","category":"Rovnice postupného vlnění","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"[[math:\\frac{10}{\\sqrt3}\\,\\mathrm{cm}]]"},{"id":"b","label":"5 cm"},{"id":"c","label":"10 cm"},{"id":"d","label":"[[math:5\\sqrt3\\,\\mathrm{cm}]]"}]', 'a', 'Fáze=2π(1/2−1/3)=π/3, takže 5=A sin(π/3)=A√3/2; A=10/√3 cm.', '2'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q21', 'mechanicke-vlneni-karolina-diagnostika-v1', '21', '{"instruction":"Urči okamžitou výchylku ve tvaru násobku amplitudy.","math":"y=A\\sin[2\\pi(t/T-x/\\lambda)],\\quad t=T/4,\\ x=\\lambda/4","category":"Rovnice postupného vlnění","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"A"},{"id":"b","label":"A/2"},{"id":"c","label":"0"},{"id":"d","label":"−A"}]', 'c', 'Fáze=2π(1/4−1/4)=0, proto y=0.', '2'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q22', 'mechanicke-vlneni-karolina-diagnostika-v1', '22', '{"instruction":"Urči okamžitou výchylku (počáteční fáze je nulová).","math":"A=6\\,\\mathrm{cm},\\ T=0{,}5\\,\\mathrm s,\\ \\lambda=4\\,\\mathrm m,\\ x=1\\,\\mathrm m,\\ t=0{,}25\\,\\mathrm s","category":"Rovnice postupného vlnění","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"−6 cm"},{"id":"b","label":"0 cm"},{"id":"c","label":"3 cm"},{"id":"d","label":"+6 cm"}]', 'd', 'Fáze=2π(0,25/0,5−1/4)=π/2. y=6 cm.', '2'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q23', 'mechanicke-vlneni-karolina-diagnostika-v1', '23', '{"instruction":"Urči velikost fázové rychlosti a vlnovou délku.","math":"y(x,t)=0{,}02\\sin(4\\pi t-\\pi x)\\quad(\\mathrm{SI})","category":"Rovnice postupného vlnění","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"v=4 m/s, λ=2 m"},{"id":"b","label":"v=2 m/s, λ=4 m"},{"id":"c","label":"v=4 m/s, λ=1 m"},{"id":"d","label":"v=1 m/s, λ=2 m"}]', 'a', 'ω=4π, k=π, tedy v=ω/k=4 m/s a λ=2π/k=2 m.', '2'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q24', 'mechanicke-vlneni-karolina-diagnostika-v1', '24', '{"instruction":"Jak vypadá prostorová část fáze u harmonické vlny postupující do záporného směru osy x?","math":"","category":"Rovnice postupného vlnění","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"[[math:\\omega t-kx+\\varphi_0]]"},{"id":"b","label":"[[math:\\omega t+kx+\\varphi_0]]"},{"id":"c","label":"[[math:kx-\\omega t^2]]"},{"id":"d","label":"[[math:\\omega x-kt]]"}]', 'b', 'Při zápisu fáze ωt−kx+φ0 se vlna šíří do +x. Pro šíření do −x změníme znaménko u kx na plus.', '2'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q25', 'mechanicke-vlneni-karolina-diagnostika-v1', '25', '{"instruction":"Pro nulovou počáteční fázi urči všechna řešení podmínky λ > 4 cm (nepředpokládej čelo vlny).","math":"x=4\\,\\mathrm{cm},\\ t=T/6,\\ y=A/2,\\ y=A\\sin[2\\pi(t/T-x/\\lambda)]","category":"Pokročilé úlohy a fyzikální interpretace","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"Jen λ = 48 cm"},{"id":"b","label":"Jen λ = 16/3 cm"},{"id":"c","label":"λ = 48 cm nebo λ = 16/3 cm"},{"id":"d","label":"Neexistuje žádné řešení"}]', 'c', 'Řešíme sin(π/3−8π cm/λ)=1/2. Při λ>4 cm vyhoví λ=48 cm (argument π/6) a λ=16/3 cm (argument −7π/6). Při požadavku na příchod čela vlny po spuštění zdroje v t=0 zbude 48 cm.', '3'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q26', 'mechanicke-vlneni-karolina-diagnostika-v1', '26', '{"instruction":"Zdroj začíná kmitat až v čase t=0. Co platí o bodu ve vzdálenosti 12 m v čase t=3 s?","math":"v=3\\,\\mathrm{m/s},\\quad x=12\\,\\mathrm m","category":"Pokročilé úlohy a fyzikální interpretace","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"Vlna už dorazila o 1 s dříve."},{"id":"b","label":"Čelo vlny dorazí až v čase 4 s; bod zatím nekmitá."},{"id":"c","label":"Bod je nutně v maximální výchylce."},{"id":"d","label":"Čelo dorazí přesně v t=3 s."}]', 'b', 'Čelo vlny dorazí v čase x/v=12/3=4 s. V t=3 s je bod ještě v počátečním klidovém stavu.', '3'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q27', 'mechanicke-vlneni-karolina-diagnostika-v1', '27', '{"instruction":"Je zadán nezredukovaný geometrický fázový rozdíl. Urči rychlost.","math":"\\Delta x=2{,}7\\,\\mathrm m,\\ |\\Delta\\varphi|=3\\pi/2,\\quad T=1{,}0\\,\\mathrm{ms}","category":"Pokročilé úlohy a fyzikální interpretace","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"900 m/s"},{"id":"b","label":"2 700 m/s"},{"id":"c","label":"3 600 m/s"},{"id":"d","label":"5 400 m/s"}]', 'c', 'λ=2π·2,7/(3π/2)=3,6 m. v=λ/T=3,6/0,001=3600 m/s.', '3'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q28', 'mechanicke-vlneni-karolina-diagnostika-v1', '28', '{"instruction":"Známe y v prvním bodě, vzdálenost i vlnovou délku, ale neznáme amplitudu ani počáteční fázi. Lze jednoznačně určit y druhého bodu?","math":"y(x_1,t)=3\\,\\mathrm{cm},\\ \\Delta x=2\\,\\mathrm m,\\ \\lambda=17\\,\\mathrm m","category":"Pokročilé úlohy a fyzikální interpretace","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"Ano, rovná se 3 cm."},{"id":"b","label":"Ano, rovná se −3 cm."},{"id":"c","label":"Ano, je nutně 0 cm."},{"id":"d","label":"Ne, bez absolutní fáze a amplitudy obecně nikoli."}]', 'd', 'Z rozdílu fází Δφ=4π/17 neznáme jednotlivou absolutní fázi ani A. Pro další y potřebujeme další podmínku (např. φ0=0 a orientaci šíření).', '3'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q29', 'mechanicke-vlneni-karolina-diagnostika-v1', '29', '{"instruction":"Rope: Za výslovného předpokladu y(0,t)=A sin(2πt/T) a šíření nahoru urči velikost výchylky.","math":"A=20\\,\\mathrm{cm},\\ T=1{,}2\\,\\mathrm s,\\ v=15\\,\\mathrm{m/s},\\ x=45\\,\\mathrm m,\\ t=4\\,\\mathrm s","category":"Pokročilé úlohy a fyzikální interpretace","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"10 cm"},{"id":"b","label":"[[math:10\\sqrt3\\,\\mathrm{cm}]]"},{"id":"c","label":"20 cm"},{"id":"d","label":"0 cm"}]', 'b', 'Zpoždění=45/15=3 s, fáze=(2π/1,2)(4−3)=5π/3. y=−10√3 cm, velikost |y|=10√3 cm ≈17,3 cm.', '3'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q30', 'mechanicke-vlneni-karolina-diagnostika-v1', '30', '{"instruction":"Zanedbáme zpoždění šíření světla. Jak rychle se šířil zvuk?","math":"s=4000\\,\\mathrm m,\\quad\\Delta t=12{,}0\\,\\mathrm s","category":"Pokročilé úlohy a fyzikální interpretace","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"300 m/s"},{"id":"b","label":"3300 m/s"},{"id":"c","label":"333,3 m/s"},{"id":"d","label":"48000 m/s"}]', 'c', 'v=s/Δt=4000/12=333,3 m/s.', '3'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q31', 'mechanicke-vlneni-karolina-diagnostika-v1', '31', '{"instruction":"Z podmínky y(0,0)=0 pro y=A sin(ωt−kx+φ0) a A>0 plyne:","math":"","category":"Pokročilé úlohy a fyzikální interpretace","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"[[math:\\varphi_0=0]] jedině"},{"id":"b","label":"[[math:\\varphi_0=\\pi/2]] jedině"},{"id":"c","label":"[[math:\\varphi_0=0]] nebo [[math:\\pi]] modulo 2π"},{"id":"d","label":"[[math:\\varphi_0=-\\pi/2]] jedině"}]', 'c', 'Podmínka sin φ0=0 připouští φ0=mπ. Zdroj může v t=0 procházet nulou v obou směrech.', '3'),
  ('mechanicke-vlneni-karolina-diagnostika-v1-q32', 'mechanicke-vlneni-karolina-diagnostika-v1', '32', '{"instruction":"Urči nezredukovaný kladný fázový rozdíl a jeho ekvivalent modulo 2π.","math":"\\lambda=4\\,\\mathrm m,\\quad\\Delta x=9\\,\\mathrm m","category":"Pokročilé úlohy a fyzikální interpretace","hint":"Nejdříve vyber správný vztah, zkontroluj jednotky a případné podmínky."}', '[{"id":"a","label":"[[math:\\frac{\\pi}{2}]] a [[math:\\frac{\\pi}{2}]]"},{"id":"b","label":"[[math:\\frac{9\\pi}{2}]] a [[math:\\frac{\\pi}{2}]]"},{"id":"c","label":"[[math:2\\pi]] a [[math:0]]"},{"id":"d","label":"[[math:\\frac{9\\pi}{2}]] a [[math:\\pi]]"}]', 'b', 'Nezredukovaný posun je 2π·9/4=9π/2. Odečtením 4π získáme π/2 modulo 2π.', '3');
